// How AI works — assessor-level technical modules AB06–AB08 (full theory).
import { X } from './aic-x-fig.js';
const P = x => ({ k: 'p', x }), H = x => ({ k: 'h', x }), S = x => ({ k: 'simple', x }), GR = x => ({ k: 'gr', x }), BR = x => ({ k: 'br', x });
const U = x => ({ k: 'ul', x }), O = x => ({ k: 'ol', x }), AP = (s, x, t) => ({ k: 'ap', s, x, t });
const FIG = (svg, cap) => ({ k: 'fig', svg, cap }), CMP = (t, h, r) => ({ k: 'cmp', t, h, r }), FLOW = (t, s, loop, v) => ({ k: 'flow', t, s, loop, v }), CARDS = c => ({ k: 'cards', c });

export const X_AB1 = [
{
 id: 'ab06', lv: 0, name: 'Reading Model Evidence: Validation and Statistics',
 goal: 'Read a model validation report like an expert: judge test design, sample sizes, confidence, baselines, ROC/AUC, calibration and regression errors.',
 map: ['Basics', 'Assessor skills', 'ISO/IEC 42001 A.6.2.4'],
 res: [['Google: Classification — ROC and AUC', 'https://developers.google.com/machine-learning/crash-course/classification/roc-and-auc'], ['scikit-learn: Probability calibration', 'https://scikit-learn.org/stable/modules/calibration.html'], ['NIST AI RMF Playbook — MEASURE', 'https://airc.nist.gov/airmf-resources/playbook/']],
 ls: [
  { t: 'What a validation report should contain', blocks: [
    S('A validation report is the **main evidence that a model works**. Before reading any numbers, check that the report answers five questions: **what was tested, on what data, against which criteria, with what results, and who signed it off.**'),
    H('Why validation reports matter to assessors'),
    P('Most of what an assessor knows about a model’s quality comes from documents produced by others. The validation report is the most important of these. It is where the organisation proves — or fails to prove — that the model is accurate enough, fair enough and robust enough for its intended use. Learning to read one critically is the single most valuable technical skill for an AI assessor.'),
    H('The structure of a good report'),
    U(['**Scope and model version** — exactly which model (version number, date, configuration) was tested, and for which intended use.', '**Acceptance criteria** — the thresholds agreed **before** testing: for example, recall ≥ 85%, approval-rate ratio ≥ 0.8 for all groups, no critical red-team findings.', '**Test data description** — source, time period, size, how it was kept separate from training data, and how it compares with the population the model will serve.', '**Methods** — metrics used and why; how fairness, robustness and security were tested.', '**Results** — overall and broken down by relevant groups and segments, with sample sizes and, ideally, confidence ranges.', '**Limitations and issues** — what was not tested, known weaknesses, open findings.', '**Conclusion and sign-off** — pass, conditional pass or fail, signed by an independent validator and accepted by the owner.']),
    FLOW('How to read a validation report', [['Check identity', 'right model, right version?'], ['Check criteria', 'set before testing?'], ['Check data', 'separate and representative?'], ['Check results', 'overall and by group'], ['Check limits', 'what was not tested?'], ['Check sign-off', 'independent?']]),
    H('Independence'),
    P('Who validated matters. In banking, model risk management standards expect validation by people independent of the developers. Independence reduces the risk that developers grade their own work generously or overlook flaws they introduced. For lower-risk AI, peer review within the team may be proportionate; for high-risk systems, independent validation should be the norm.'),
    BR('A validation report is to a model what a **control test working paper** is to a control: it should be reproducible, evidence-based, and reviewed. Apply the same scepticism you would apply to a management self-assessment.'),
    AP(['Confirm the report refers to the deployed model version.', 'Check acceptance criteria pre-date the test results.', 'Check results are broken down by relevant groups.', 'Check the validator’s independence and the sign-off.'])],
   ex: 'A report showing excellent results for “credit model v2” is not evidence for the v3 now in production. Always match the version in the report to the version in the model registry.' },
  { t: 'Sample sizes, confidence and uncertainty', blocks: [
    S('A result measured on a **small sample is uncertain**. “80% accurate” on 50 cases could really be anywhere from about 69% to 91%. Always ask **how many cases** a number is based on.'),
    H('Every metric is an estimate'),
    P('When a team reports that a model is 80% accurate, they mean it was 80% accurate on a particular test set. If they had used a different sample of cases, the number would be slightly different. The smaller the sample, the larger that variation. Statisticians express this as a **confidence interval** — a range within which the true value probably lies.'),
    FIG(X.ci, 'The same 80% result, measured on different sample sizes.'),
    H('Why this matters especially for fairness'),
    P('Overall test sets may be large, but **subgroups are often small**. A model might be tested on 10,000 applicants, of whom only 120 are over 60 or from a particular nationality. Group-level metrics on 120 cases can swing widely by chance. A finding that “group B’s approval rate is 15 points lower” may be real or may be noise — the assessor needs to know the sample size and ideally a confidence range or statistical test.'),
    H('A rule of thumb'),
    P('For a percentage around 50–80%, the 95% confidence range is roughly ±10 points with 100 cases, ±3 points with 1,000 cases and ±1 point with 10,000 cases. You do not need to calculate precisely; you need to recognise when a number is too uncertain to support a conclusion — in either direction.'),
    CMP('Interpreting group results', ['Situation', 'What to conclude'], [['Large gap, large samples', 'Likely real — investigate cause'], ['Large gap, small samples', 'Possibly noise — gather more data or test differently'], ['No gap, small samples', 'Not proof of fairness — the test may be too weak to detect a gap'], ['Small gap, large samples', 'Real but possibly minor — judge against criteria']]),
    BR('This is the same logic as **audit sampling**: a conclusion from 5 samples is weaker than one from 60. Ask for sample sizes as routinely as you would ask for a sampling methodology.'),
    AP(['Ask for the number of cases behind every key metric, overall and per group.', 'Treat conclusions from very small groups with caution.', 'Where groups are small, ask how the team compensated (more data, pooled periods, statistical tests).'])],
   ex: 'A hiring tool vendor reported “no gender bias” based on 40 female applicants. With so few cases, even a large difference could go undetected — the evidence was too weak to support the claim.' },
  { t: 'Baselines: compared with what?', blocks: [
    S('A number means little on its own. “85% accurate” could be excellent or useless depending on **what it is compared with**: the current process, a simple rule, or doing nothing.'),
    H('Why baselines matter'),
    P('Every model should be compared with at least one **baseline** — a simpler alternative. If a sophisticated model only slightly outperforms a basic rule, its extra complexity, cost and explainability challenges may not be justified. If it underperforms the current human process, it should not replace it.'),
    U(['**Naive baseline** — always predicting the most common outcome. For fraud at 0.1% prevalence, “never fraud” is 99.9% accurate. Any useful model must beat this on meaningful metrics.', '**Simple rule baseline** — for example, “flag transactions above AED 10,000 from new devices”. Shows what the model adds beyond common sense.', '**Current process baseline** — how human decisions or the existing model perform today. This is usually the most important comparison for business and risk decisions.', '**Previous version** — for updates, the new version should be compared with the one it replaces.']),
    CMP('Example: fraud detection', ['Approach', 'Recall', 'Precision', 'Alerts / day'], [['Never flag (naive)', '0%', '—', '0'], ['Rule: > AED 10,000 + new device', '45%', '12%', '900'], ['Current model v3', '78%', '30%', '650'], ['Proposed model v4', '84%', '34%', '620']]),
    P('In this example the new model catches more fraud **and** raises fewer alerts than both the rule and the current model — a clear improvement. If v4 had higher recall but doubled the alerts, the decision would be a trade-off requiring business judgement.'),
    H('Baselines for fairness'),
    P('Fairness should also be compared with the baseline. If the current human process approves group B at 65% of group A’s rate and the model raises it to 85%, the model may be an improvement even if it is not perfect. Conversely, a model that makes an existing disparity worse is a serious concern.'),
    BR('Baselines answer the question every risk committee should ask: **is this better than what we do today, and by enough to justify the new risks?**'),
    AP(['Ask what baseline the model was compared with.', 'Ask for the current process’s performance and fairness.', 'Check the improvement justifies added complexity.'])],
   ex: 'A churn model boasted 92% accuracy — but 91% of customers never churn, so “predict no churn for everyone” scored 91%. The model added almost nothing until the team switched to recall and precision on churners.' },
  { t: 'ROC curves, AUC and the Gini coefficient', blocks: [
    S('**AUC** summarises how well a model **ranks** positive cases above negative ones, across all possible thresholds. 0.5 is random guessing; 1.0 is perfect. Credit teams often report the same idea as a **Gini** coefficient.'),
    H('The ROC curve'),
    P('A classifier produces scores, and a threshold converts scores into decisions. Each threshold gives a particular **true positive rate** (recall) and **false positive rate**. Plotting these pairs for every possible threshold produces the **ROC curve** (receiver operating characteristic). A model that separates positives from negatives well rises steeply towards the top-left corner; a model no better than chance follows the diagonal.'),
    FIG(X.roc, 'ROC curves. The area under each curve is the AUC.'),
    H('AUC and Gini'),
    P('The **area under the ROC curve (AUC)** gives a single number between 0.5 and 1.0. It can be read as the probability that a randomly chosen positive case receives a higher score than a randomly chosen negative case. In credit risk, the **Gini coefficient** (also called accuracy ratio) is commonly used and equals **2 × AUC − 1**: an AUC of 0.80 corresponds to a Gini of 0.60.'),
    CMP('Rough interpretation (varies by domain)', ['AUC', 'Gini', 'Typical reading'], [['0.50', '0.00', 'No better than random'], ['0.60–0.70', '0.20–0.40', 'Weak'], ['0.70–0.80', '0.40–0.60', 'Acceptable to good'], ['0.80–0.90', '0.60–0.80', 'Good to strong'], ['> 0.90', '> 0.80', 'Very strong — check for leakage']]),
    H('What AUC does not tell you'),
    P('AUC ignores the threshold actually used, so it does not show how many false alarms or missed cases occur in practice. It does not show whether scores are **calibrated** (whether 0.3 means 30% risk). It can hide poor performance for a subgroup. And a suspiciously high AUC is a classic sign of **data leakage**. Use AUC to compare models, but always look at precision, recall and group results at the operating threshold.'),
    BR('AUC is a **summary indicator**, like an overall control maturity score. Useful for comparison, insufficient on its own for assurance.'),
    AP(['Ask for AUC or Gini on held-out data, by segment.', 'Treat very high values as a prompt to check for leakage.', 'Always also review metrics at the operating threshold.'])],
   ex: 'A credit model reports Gini 0.62 overall, but 0.41 for self-employed applicants — the average hid a much weaker model for one segment.' },
  { t: 'Calibration and regression errors', blocks: [
    S('**Calibration** asks whether a score **means what it says**: of people given a 20% risk score, do about 20% actually default? For models that predict numbers, **error measures** tell you how far off predictions usually are.'),
    H('Why calibration matters'),
    P('Many decisions use scores as probabilities: pricing a loan, setting insurance premiums, prioritising cases. If a model says 20% risk but the true rate is 35%, prices and provisions are wrong. Calibration can also differ between groups: the same score may correspond to different real risks for different populations, which is itself a fairness concern.'),
    FIG(X.calib, 'A calibration plot. Points on the diagonal mean the scores are accurate probabilities.'),
    P('Calibration is checked by grouping cases by predicted score and comparing the average prediction with the actual outcome rate in each group, often shown as a **calibration plot** or summarised with a **Brier score** (the average squared difference between predicted probability and outcome; lower is better). A well-ranking model (high AUC) can still be poorly calibrated, and calibration can be corrected after training.'),
    H('Errors for numeric predictions'),
    U(['**Mean absolute error (MAE)** — the average size of errors in real units: “on average, our claim-cost estimate is AED 2,300 off”. Easy to explain.', '**Root mean squared error (RMSE)** — penalises large errors more heavily; useful when big misses are especially costly.', '**Mean absolute percentage error (MAPE)** — error as a percentage of the actual value; common in forecasting, misleading when actual values are near zero.', '**Bias (mean error)** — whether predictions are systematically too high or too low.']),
    CMP('Which to ask for', ['Model type', 'Key evidence'], [['Probability scores used for decisions or pricing', 'Calibration plot, Brier score, calibration by group'], ['Regression (amounts, times)', 'MAE and bias, by segment'], ['Forecasting', 'MAPE or MAE over several periods, including unusual ones']]),
    BR('Calibration is like **reconciliation**: do predicted totals agree with actual outcomes? A model that systematically over- or under-predicts is like a ledger that never reconciles.'),
    AP(['For score-based decisions, ask for a calibration analysis overall and by group.', 'For numeric predictions, ask for MAE and bias by segment.', 'Check whether calibration is monitored after launch.'])],
   ex: 'An insurer’s pricing model was well calibrated overall but over-predicted claims for drivers from one emirate by 30% — leading to higher premiums that were not justified by actual risk.' },
  { t: 'Real-world scenario: challenging a vendor’s test results', blocks: [
    S('Vendors often present impressive numbers. A short list of questions — **on what data, how many, compared with what, for whom, at which threshold** — quickly reveals whether the evidence is strong.'),
    H('The situation'),
    P('A UAE bank is evaluating a vendor’s AI tool that prioritises anti-money-laundering alerts. The vendor’s brochure claims: “AUC 0.94. Reduces false positives by 60%. Tested and validated.” The bank’s analyst, experienced in AML controls but new to AI, prepares questions.'),
    H('The questions and answers'),
    O(['**On what data?** — Answer: a pooled dataset from three European banks, 2021–2023. *Concern:* different customer base, products and typologies from the UAE bank.', '**How many cases?** — 1.2 million alerts, of which 4,800 were confirmed suspicious. *Reasonable overall, but only a few hundred involve trade-based patterns common in the UAE.*', '**Compared with what?** — Compared with “alerts reviewed in arrival order”. *A weak baseline; the bank already uses risk-based ordering.*', '**For whom?** — No breakdown by customer segment or nationality. *Fairness and coverage unknown.*', '**At which threshold?** — “60% fewer false positives” is at a threshold where recall falls to 88%. *So 12% of suspicious cases would be deprioritised — a material regulatory risk.*', '**AUC 0.94?** — On historical data. *Very high; ask whether any features used information only available after investigation (leakage).*']),
    H('The decision'),
    P('The bank does not reject the tool. It requires a **proof of concept on its own historical alerts**, compared with its current risk-based ordering, with results by segment and a fixed recall floor agreed with the MLRO. The tool runs in **shadow mode** for three months before any change to alert handling.'),
    BR('This is vendor assurance with technical depth: you are not taking the SOC 2 report at face value, and you should not take model metrics at face value either.'),
    AP(['Ask the five questions: data, size, baseline, groups, threshold.', 'Insist on testing on your own data before relying on vendor claims.', 'Use shadow mode before changing live processes.'], '', 'Five questions for any model claim')],
   ex: 'Testing on the bank’s own alerts showed a 35% (not 60%) reduction in false positives at the required recall — still valuable, and now based on evidence the bank could defend to its regulator.' }
 ],
 sum: ['Read a validation report for identity, criteria, data, results, limits and sign-off.', 'Every metric is an estimate; small samples — especially small groups — are uncertain.', 'Always ask “compared with what?” — the current process is the key baseline.', 'AUC/Gini summarise ranking quality but hide threshold effects, calibration and subgroup gaps.', 'Calibration checks whether scores mean what they say, overall and by group.', 'Challenge vendor claims with five questions and test on your own data.'],
 q: [
  { t: 'A report shows 80% accuracy measured on 50 cases. What is the main concern?', o: ['The result proves the model is ready for production use', 'Fifty cases is the regulatory minimum, so it is reliable', 'The result is very uncertain; the true value could be far from 80%', 'The model is clearly overfitting and must be retrained'], a: 2, x: 'With 50 cases the 95% confidence range is roughly ±11 points.' },
  { t: 'A credit model has an AUC of 0.80. What is its Gini coefficient?', o: ['0.40', '0.80', '1.60', '0.60'], a: 3, x: 'Gini = 2 × AUC − 1 = 0.60.' },
  { t: 'What does calibration check?', o: ['Whether scores match actual outcome rates', 'Whether the model is faster than the baseline', 'Whether the training data is encrypted', 'Whether the model has enough layers'], a: 0, x: 'A calibrated model’s 20% score corresponds to about 20% actual outcomes.' },
  { t: 'Which baseline is usually most important for an approval decision?', o: ['A competitor’s model published in a journal', 'The current process the model would replace', 'The very first model the team ever built', 'A random guess generated for comparison'], a: 1, x: 'The key question is whether the model improves on what is done today.' },
  { t: 'A fraud model shows AUC 0.99 on historical data. What should an assessor do first?', o: ['Approve it immediately', 'Ask for a larger model', 'Check for data leakage', 'Ignore it, AUC is meaningless'], a: 2, x: 'Suspiciously high scores often indicate leakage of future information.' },
  { t: 'A vendor reports “no bias” from 40 applicants in a group. Best response?', o: ['Accept the claim as proven', 'Reject the vendor outright', 'Ask the vendor to remove that group from the data', 'Note the evidence is too weak and request more testing'], a: 3, x: 'Small samples cannot reliably detect differences, so the claim is not well supported.' }
 ]
},
{
 id: 'ab07', lv: 0, name: 'Monitoring Numbers: Drift, Decay and Alerts',
 goal: 'Understand how live AI systems are monitored — data drift, concept drift, PSI, performance decay, fairness monitoring and alert design — and how to judge whether monitoring works.',
 map: ['Basics', 'Assessor skills', 'ISO/IEC 42001 A.6.2.6', 'EU AI Act Art. 72'],
 res: [['Google Cloud: MLOps and continuous monitoring', 'https://cloud.google.com/architecture/mlops-continuous-delivery-and-automation-pipelines-in-machine-learning'], ['Evidently AI: data drift explained', 'https://www.evidentlyai.com/ml-in-production/data-drift'], ['NIST AI RMF Playbook — MEASURE / MANAGE', 'https://airc.nist.gov/airmf-resources/playbook/']],
 ls: [
  { t: 'Why models decay', blocks: [
    S('A model learns patterns from the past. When the world changes, those patterns become less accurate. This gradual loss of quality is called **model decay**, and it happens even if nobody touches the model.'),
    H('The world does not stand still'),
    P('Customer behaviour, products, prices, regulations, fraud tactics and even the language people use all change over time. A model trained on 2023 data assumes 2023 patterns. In 2025 those assumptions may no longer hold. Unlike a software bug, decay rarely announces itself: the model keeps producing confident outputs, but they are wrong more often.'),
    H('Common causes'),
    CARDS([['New populations', 'New customer segments or markets.', 'A bank expands to young gig workers'], ['Economic change', 'Rates, inflation, unemployment shift.', 'Default patterns change after rate rises'], ['Behaviour change', 'People act differently.', 'Shopping moves online'], ['Adversaries adapt', 'Fraudsters learn to evade the model.', 'New scam patterns'], ['Upstream data changes', 'A source system changes format or meaning.', 'A field starts recording in a new unit'], ['Feedback loops', 'The model’s own decisions shape future data.', 'Declined applicants never generate repayment data']]),
    H('Feedback loops deserve special attention'),
    P('When a model’s decisions influence the data it later learns from, problems can reinforce themselves. If a credit model declines a group, no repayment data is collected for that group, so the next model has even less evidence about them. If a policing or inspection model sends more attention to an area, more incidents are recorded there, appearing to confirm the model. Monitoring and periodic review must look for these loops.'),
    BR('Treat a live model like any key control that can degrade: it needs **ongoing monitoring with thresholds and owners**, not a one-time test at implementation.'),
    AP(['Ask what could change in this model’s environment and how it would be detected.', 'Check for feedback loops where decisions affect future training data.', 'Confirm each live model has a monitoring plan and owner.'])],
   ex: 'A fraud model performed well for a year, then missed a new “authorised push payment” scam pattern entirely — fraudsters had adapted, and the model had never seen the new behaviour.' },
  { t: 'Data drift and the population stability index', blocks: [
    S('**Data drift** means the inputs a model receives have changed compared with its training data. The **population stability index (PSI)** is a common way to measure how much a variable’s distribution has shifted.'),
    H('Measuring change in inputs'),
    P('To detect data drift, teams compare the distribution of each important input (and of the model’s scores) in a recent period with the distribution in the training or reference period. If incomes, ages, transaction amounts or product mixes look very different, the model may be operating outside the conditions it learned from.'),
    FIG(X.psi, 'Income distribution has shifted towards higher bands since training.'),
    H('How PSI works'),
    P('PSI divides a variable into bands (for example, income ranges), compares the share of cases in each band between the reference and current periods, and sums a weighted measure of the differences. A common rule of thumb in credit risk is: **below 0.1** — stable; **0.1 to 0.25** — moderate shift worth watching; **above 0.25** — significant shift requiring investigation. Other measures, such as the Kolmogorov–Smirnov statistic or Jensen–Shannon distance, serve the same purpose.'),
    CMP('Interpreting PSI (common rule of thumb)', ['PSI', 'Meaning', 'Typical action'], [['< 0.10', 'Stable', 'Routine monitoring'], ['0.10 – 0.25', 'Moderate shift', 'Investigate causes; watch performance'], ['> 0.25', 'Significant shift', 'Escalate; consider recalibration or retraining']]),
    H('Drift is a warning, not a verdict'),
    P('Data drift does not automatically mean the model is wrong. A shift in incomes might not affect accuracy if the model handles it well. But drift is an early warning that comes **before** outcomes are known — often months before defaults or fraud losses appear. That makes it valuable for timely action.'),
    BR('PSI is a **key risk indicator** with thresholds — the same concept as KRIs in operational risk. Check that thresholds are defined, monitored and acted on.'),
    AP(['Ask which inputs and scores are monitored for drift, and how often.', 'Ask for the thresholds and recent values.', 'Check what happened the last time a threshold was breached.'])],
   ex: 'After a new salary-transfer partnership, the PSI on applicant income rose to 0.27. The team checked performance on early outcomes, recalibrated the model and documented the decision.' },
  { t: 'Concept drift and performance decay', blocks: [
    S('**Concept drift** means the relationship between inputs and outcomes has changed: the same inputs no longer lead to the same results. It shows up as **falling performance** once real outcomes are known.'),
    H('Different from data drift'),
    P('With data drift, the inputs change. With concept drift, the **meaning** of inputs changes. For example, before a pandemic, frequent online purchases might have indicated affluence; during lockdowns, everyone shopped online, so the signal lost its meaning. Fraud is a classic case: as fraudsters adapt, the features that once indicated fraud stop working.'),
    H('Measuring performance in production'),
    P('Performance can only be measured when **true outcomes** become known — and that often takes time. Fraud may be confirmed within weeks; loan defaults may take 6 to 12 months; employee performance may take a year. Monitoring therefore combines: **leading indicators** (data drift, score distribution, override rates, complaint rates) available immediately, and **lagging indicators** (precision, recall, error rates, calibration) calculated once outcomes mature.'),
    CMP('Leading and lagging monitoring signals', ['Signal', 'Type', 'When available'], [['Input drift (PSI)', 'Leading', 'Immediately'], ['Score distribution shift', 'Leading', 'Immediately'], ['Human override rate', 'Leading', 'Immediately'], ['Complaints and appeals', 'Leading', 'Days to weeks'], ['Precision / recall', 'Lagging', 'When outcomes are known'], ['Default rate by score band', 'Lagging', 'Months']]),
    H('Comparing with the validation baseline'),
    P('Live performance should be compared with the results at validation. A model validated at 85% recall that now achieves 70% has decayed materially. Thresholds should define how much decline triggers review, recalibration, retraining or withdrawal.'),
    BR('Leading and lagging indicators are familiar from risk reporting. For AI, insist on **both**: lagging metrics alone discover problems too late.'),
    AP(['Ask how long outcomes take to mature for this model.', 'Check both leading and lagging indicators are monitored.', 'Compare current performance with validation results.'])],
   ex: 'A collections-prioritisation model’s recall fell from 82% to 64% over nine months as customers’ payment behaviour changed after a new instalment product launched — detected only because the team tracked outcomes monthly.' },
  { t: 'Monitoring fairness and outcomes over time', blocks: [
    S('A model that was fair at launch may become unfair later. **Fairness must be monitored**, not just tested once — using the same group metrics chosen during validation.'),
    H('Why fairness can drift'),
    P('Group compositions change; data quality for some groups may deteriorate; new products may suit some customers better; feedback loops may compound small differences. Human behaviour around the model can also shift — reviewers may override more for some groups than others. Any of these can move fairness metrics after deployment.'),
    H('What to monitor'),
    U(['**Outcome rates by group** — approval, selection or flag rates, with the four-fifths ratio or chosen threshold.', '**Error rates by group** — once outcomes are known: false positives and false negatives per group.', '**Override patterns** — whether humans override the model more often for particular groups.', '**Complaints and appeals by group**, where data is available.', '**Population mix** — whether the share of each group is changing.']),
    FLOW('Fairness monitoring cycle', [['Calculate group metrics', 'monthly or quarterly'], ['Compare with thresholds', 'and with launch values'], ['Investigate breaches', 'data, process, model'], ['Act and record', 'fix, accept or escalate'], ['Report', 'to risk committee']]),
    H('Data challenges'),
    P('Group information is often incomplete in production. Organisations may need lawful mechanisms to measure fairness — voluntary data, secure analysis environments, or statistically validated estimation — each with privacy implications that must be assessed and documented.'),
    BR('Fairness metrics are **outcome KRIs**. Report them alongside performance KRIs, with the same governance: thresholds, owners and escalation.'),
    AP(['Check fairness metrics from validation are carried into monitoring.', 'Check thresholds, frequency and recent results.', 'Check override analysis by group.'])],
   ex: 'Six months after launch, a hiring tool’s shortlisting ratio for applicants over 45 dropped from 0.86 to 0.71, after a new job family was added. Monitoring caught it; the job family was excluded until retested.' },
  { t: 'Designing alerts, thresholds and dashboards', blocks: [
    S('Monitoring only helps if someone **sees the signal and acts**. Good monitoring has **clear thresholds, named owners, response times and records of action** — not just dashboards nobody reads.'),
    H('From metrics to action'),
    P('Many organisations build attractive dashboards that nobody looks at. Effective monitoring defines, for each important metric: a **threshold** (green/amber/red), an **owner** who receives the alert, a **response time**, and the **actions** expected — investigate, recalibrate, add human review, roll back or switch off. Every breach and its handling should be recorded.'),
    CMP('Example monitoring plan for a credit model', ['Metric', 'Amber', 'Red', 'Owner / response'], [['PSI on key inputs', '> 0.10', '> 0.25', 'Model owner, 5 days'], ['Approval rate change vs. last month', '± 5 pts', '± 10 pts', 'Credit risk, 2 days'], ['Approval-rate ratio (any group)', '< 0.85', '< 0.80', 'Model owner + compliance, 5 days'], ['Recall on matured outcomes', '< 80%', '< 75%', 'Model risk, 10 days'], ['Human override rate', '> 8%', '> 15%', 'Head of lending, 5 days']]),
    H('Avoiding alert fatigue'),
    P('Too many alerts lead people to ignore them. Thresholds should be calibrated so that alerts are meaningful, related alerts are grouped, and low-severity signals are summarised in periodic reports rather than sent individually.'),
    H('Evidence of operation'),
    P('For assurance purposes, the important evidence is not the dashboard design but the **history**: alerts raised, investigations performed, decisions taken. An assessor should be able to trace a specific breach to its resolution.'),
    BR('This is **monitoring control design**: precision of thresholds, ownership, timeliness and evidence. Test it as you would test a reconciliation or exception-report control.'),
    AP(['Request the monitoring plan with thresholds and owners.', 'Select recent breaches and trace them to documented actions.', 'Check alert volumes are manageable.'])],
   ex: 'An auditor found 14 red alerts in six months on a pricing model — and no investigation records. The dashboard existed; the control did not operate.' },
  { t: 'Real-world scenario: the silent decline', blocks: [
    S('Problems in live AI rarely arrive as a single failure. More often, several small signals appear over months. Monitoring that **connects the signals** catches the decline early.'),
    H('The situation'),
    P('An Indian insurer uses an AI model to fast-track simple motor claims. At launch, 40% of claims were fast-tracked with very low error. Nine months later, the claims director feels “something is off”, and asks the GRC team to investigate.'),
    H('The signals, in hindsight'),
    O(['**Month 3:** a garage network in two cities changed its invoicing software; invoice formats changed (upstream data change). PSI on “repair amount” rose to 0.14 — amber, noted but not investigated.', '**Month 5:** the fast-track rate rose from 40% to 52% (prediction drift). Seen as a success.', '**Month 6:** human override rate on fast-tracked claims fell to almost zero as staff trusted the model more (automation bias).', '**Month 8:** complaints from customers whose claims were later reopened doubled.', '**Month 9:** post-payment audits found inflated repair invoices concentrated in the two cities.']),
    H('What went wrong'),
    P('Each signal was visible, but none had an owner responsible for connecting them. Amber alerts were not investigated, rising fast-track rates were treated as good news, and falling overrides were not seen as a warning.'),
    H('The fix'),
    U(['A single **monitoring owner** reviews all signals monthly.', 'Amber alerts require a written assessment within 10 days.', 'A sudden rise in automation (fast-track rate) is treated as a **trigger for review**, not just a success metric.', 'A random 5% sample of fast-tracked claims is reviewed by humans, maintaining independent checks.', 'Upstream data changes from partners must be notified and assessed.']),
    BR('This is a classic control-environment lesson: indicators existed, but **ownership and escalation** failed. AI monitoring needs governance, not just tooling.'),
    AP(['Look for signals that were seen but not acted upon.', 'Check for a single owner who connects monitoring signals.', 'Treat sudden improvements as triggers for review.'])],
   ex: 'After the fix, a similar invoice-format change at another garage network was caught within three weeks by the amber-alert review.' }
 ],
 sum: ['Models decay as the world changes, even when no code changes.', 'Data drift (inputs change) is an early warning; PSI > 0.25 is commonly treated as significant.', 'Concept drift changes the meaning of inputs; it appears as falling performance.', 'Combine leading indicators (drift, overrides, complaints) with lagging ones (recall, error rates).', 'Monitor fairness after launch with the same group metrics used at validation.', 'Monitoring works only with thresholds, owners, response times and recorded actions.'],
 q: [
  { t: 'A model’s input distribution has shifted compared with training. This is:', o: ['Concept drift', 'Overfitting', 'Calibration', 'Data drift'], a: 3, x: 'Data drift is a change in the inputs the model receives.' },
  { t: 'A PSI of 0.30 on a key input usually means:', o: ['A significant shift that should be investigated', 'The model is perfectly stable and needs no action', 'The model must be deleted on the same day', 'The model is now well calibrated for all groups'], a: 0, x: 'Above about 0.25 is commonly treated as a significant shift.' },
  { t: 'Why are leading indicators important in monitoring?', o: ['They fully replace the need for outcome data', 'They warn of problems before outcomes are known', 'They are required by name in every AI law', 'They measure fairness precisely for each group'], a: 1, x: 'Outcomes may take months; drift and overrides give early warning.' },
  { t: 'Fraudsters change tactics so old patterns no longer predict fraud. This is:', o: ['Data leakage', 'Population stability', 'Concept drift', 'Underfitting'], a: 2, x: 'The relationship between inputs and outcome has changed.' },
  { t: 'Which best shows a monitoring control is operating?', o: ['A well-designed dashboard shown at the committee', 'A monitoring policy approved by the board', 'A vendor brochure describing monitoring features', 'Records of breaches traced to investigation and action'], a: 3, x: 'Evidence of action on breaches demonstrates operation.' },
  { t: 'A model’s automation rate suddenly rises from 40% to 52%. Best response?', o: ['Treat it as a trigger for review', 'Celebrate and reduce monitoring', 'Raise the threshold further', 'Stop collecting outcome data'], a: 0, x: 'Sudden shifts in outputs can signal drift or abuse and should be investigated.' }
 ]
},
{
 id: 'ab08', lv: 0, name: 'Testing Generative AI and Agents',
 goal: 'Understand how LLM applications and agents are evaluated — test sets, groundedness, model-graded evaluation, red-teaming coverage, agent and tool security, MCP — and what good evidence looks like.',
 map: ['Basics', 'Assessor skills', 'NIST AI 600-1', 'OWASP LLM Top 10'],
 res: [['OWASP Top 10 for LLM Applications 2025', 'https://genai.owasp.org/llm-top-10/'], ['NIST AI 600-1 Generative AI Profile', 'https://doi.org/10.6028/NIST.AI.600-1'], ['Model Context Protocol — security best practices', 'https://modelcontextprotocol.io/'], ['MITRE ATLAS', 'https://atlas.mitre.org/']],
 ls: [
  { t: 'Why testing GenAI is different', blocks: [
    S('Traditional models have one correct answer to compare with. Generative AI produces **open-ended text, images or actions**, so testing needs a mix of **automatic checks, rubrics, human review and adversarial testing**.'),
    H('The challenge'),
    P('A fraud model either flagged a transaction or it did not, and you can count right and wrong answers. A chatbot asked “What is the fee for an international transfer?” might give many acceptable answers in different wording — and some unacceptable ones that look almost identical. The output space is effectively unlimited, inputs are unpredictable, and the same input can produce different outputs. Testing therefore cannot be exhaustive; it must be **systematic, risk-based and continuous**.'),
    H('Four complementary approaches'),
    CARDS([['Automatic checks', 'Rules that verify facts, formats or forbidden content.', 'Does the answer contain the correct fee?'], ['Rubric-based grading', 'Score answers against defined criteria, by people or by a judge model.', 'Correct, complete, grounded, polite'], ['Human review', 'Experts assess samples for quality and harm.', 'Compliance reviews 100 answers'], ['Adversarial testing', 'Red-teamers try to break it.', 'Jailbreaks, injections, misuse']]),
    H('What “good” means'),
    P('Before testing, the organisation must define what good behaviour looks like for this application: which questions it should answer, which it must refuse or escalate, what sources it may rely on, what tone and languages it must support, and which errors are unacceptable (for example, any wrong fee or medical advice). These definitions become **acceptance criteria**.'),
    BR('Think of GenAI testing as **testing a new employee’s judgement** rather than testing a calculation: you use scenarios, rubrics and supervision, not a single answer key.'),
    AP(['Ask for the written definition of acceptable and unacceptable behaviour.', 'Check that testing combines automatic, rubric, human and adversarial methods.', 'Check zero-tolerance error types are defined.'])],
   ex: 'A bank defines three zero-tolerance errors for its chatbot — wrong fees, promises of approval, and disclosure of another customer’s data — and tests specifically for each before every release.' },
  { t: 'Building an evaluation set', blocks: [
    S('An **evaluation set** is a curated list of test inputs with expected behaviours. It is the backbone of GenAI quality assurance — and it should **grow every time a real failure is found**.'),
    H('What to include'),
    U(['**Common questions** — drawn from real user logs or anticipated use (with personal data removed).', '**Hard cases** — ambiguous questions, multi-part questions, edge cases in policies.', '**Should-refuse or escalate cases** — out-of-scope topics, requests for advice the system must not give, complaints needing a human.', '**Adversarial cases** — prompt injections, jailbreak attempts, attempts to extract data.', '**Every supported language and dialect**, and accessibility needs.', '**Regression cases** — every failure found in production, added permanently so it never returns.']),
    FLOW('Evaluation set lifecycle', [['Draft from real use', 'and risk analysis'], ['Define expected behaviour', 'per case'], ['Review with experts', 'compliance, product'], ['Run on every change', 'automatically'], ['Add new failures', 'from production']]),
    H('Size and coverage'),
    P('There is no magic number. Many organisations start with a few hundred cases and grow to thousands. Coverage matters more than size: every intended task, every product, every language, every risk category and every zero-tolerance error type should be represented. A coverage map — topics and risks versus number of test cases — makes gaps visible.'),
    H('Keeping it honest'),
    P('Evaluation sets must not be used to tune prompts so tightly that the system memorises them. Keeping a **hidden hold-out portion** that developers do not see protects against “teaching to the test”.'),
    BR('An evaluation set is like a **test script library** for a critical system, plus a regression suite. Ask for its coverage map just as you would ask for test coverage in a system implementation audit.'),
    AP(['Request the evaluation set’s coverage map.', 'Check that all languages and risk categories are covered.', 'Check production failures are added as regression cases.', 'Check a hold-out portion exists.'])],
   ex: 'A government services chatbot’s evaluation set grew from 250 to 1,900 cases in a year — 60% of new cases came from real user questions the system had handled badly.' },
  { t: 'Groundedness, accuracy and model-graded evaluation', blocks: [
    S('**Groundedness** checks whether every claim in an answer is **supported by the sources** the system retrieved. **Model-graded evaluation** uses another AI model as a judge to score answers at scale — but the judge itself must be checked.'),
    H('Groundedness and faithfulness'),
    P('For RAG applications, the most important quality is that answers stay faithful to approved sources. A groundedness evaluation breaks an answer into claims and checks each against the retrieved passages. An answer can be **correct but ungrounded** (true, but not supported by the sources — so it came from the model’s memory) or **grounded but incomplete**. Retrieval quality is measured separately: did the system find the right passages in the first place?'),
    CMP('Common RAG evaluation measures', ['Measure', 'Question'], [['Retrieval relevance', 'Did search return the passages that contain the answer?'], ['Groundedness / faithfulness', 'Is every claim supported by the retrieved passages?'], ['Answer correctness', 'Is the answer factually right?'], ['Completeness', 'Did it answer all parts of the question?'], ['Citation accuracy', 'Do citations point to passages that actually support the claim?']]),
    H('Model-graded evaluation (“LLM as judge”)'),
    P('Human review of thousands of answers is expensive. Many teams use a separate model to grade answers against a rubric — for example, “score 1–5 for groundedness, explain why”. This scales well, but judge models have biases: they may prefer longer answers, their own style, or be fooled by confident wording. Good practice is to **validate the judge** by comparing its scores with expert human scores on a sample, measure agreement, and periodically re-check.'),
    BR('A judge model is an **automated control**. Like any automated control, it needs initial validation and periodic re-performance by humans to confirm it still works.'),
    AP(['Ask for groundedness and retrieval metrics separately.', 'If a judge model is used, ask how it was validated against human reviewers.', 'Check citation accuracy is tested, not just presence of citations.'])],
   ex: 'A legal-research assistant scored 96% groundedness by its judge model, but human lawyers found 8% of citations pointed to the wrong paragraph — the judge had checked that citations existed, not that they supported the claim.' },
  { t: 'Red-teaming: planning and coverage', blocks: [
    S('**Red-teaming** is deliberate, structured attempts to make an AI system fail or misbehave. Its value depends on **scope, skill, coverage and follow-up** — not just on running a few clever prompts.'),
    H('What red teams test'),
    U(['**Security** — prompt injection (direct and indirect), system-prompt extraction, data exfiltration, tool misuse.', '**Safety and content** — harmful, hateful, sexual or dangerous outputs; self-harm content.', '**Misuse** — using the system for fraud, evasion of controls (e.g. KYC), generating misinformation.', '**Fairness** — different quality or treatment by language, name, nationality, gender.', '**Reliability** — confident wrong answers on high-stakes topics.', '**Agent behaviour** — unsafe actions, exceeding permissions, runaway loops.']),
    H('Planning a red-team exercise'),
    FLOW('Red-team lifecycle', [['Scope and rules', 'systems, goals, limits'], ['Threat model', 'OWASP LLM, MITRE ATLAS'], ['Test', 'manual + automated'], ['Rate findings', 'severity, likelihood'], ['Fix and retest'], ['Add to regression set']]),
    H('Judging red-team evidence'),
    P('A red-team report should show the **scope** (what was in and out), the **team** (skills, independence), the **coverage** (which threat categories, languages and entry points), the **findings** with severity, and the **remediation and retest** status. A report listing only successes (“we couldn’t break it”) without coverage detail provides little assurance. Automated red-teaming tools add scale but should complement, not replace, skilled humans.'),
    BR('Treat red-teaming exactly like a **penetration test**: scoped, independent, risk-rated findings, tracked remediation, retest evidence.'),
    AP(['Check the red-team scope covers all relevant threat categories and languages.', 'Check team independence and skills.', 'Check findings are rated and remediated, with retest evidence.', 'Check findings become permanent regression tests.'])],
   ex: 'A red team found that writing in a mix of Arabic and English bypassed a chatbot’s content filters. The fix was added, and 50 mixed-language attacks became part of the permanent test suite.' },
  { t: 'Testing agents, tools and MCP connections', blocks: [
    S('Agents can **take actions**, so testing must cover not only what they say but **what they do** — which tools they call, with what permissions, and whether they can be tricked into harmful actions.'),
    H('The agent attack surface'),
    P('An agent combines a model, instructions, tools and data. Each tool — search, email, database, payment system — extends what a manipulated or mistaken agent can do. Tools are increasingly connected through the **Model Context Protocol (MCP)**, which lets agents discover and use tool servers in a standard way. This is convenient, but it means a poorly designed or malicious tool server can influence the agent, and over-broad permissions can expose systems.'),
    FIG(X.agentPerm, 'Grouping tools by risk makes approval rules clear.'),
    H('What to test'),
    U(['**Permission boundaries** — can the agent access data or perform actions beyond the user’s own rights or its defined role?', '**Approval enforcement** — are high-risk actions blocked until a human approves, even if the agent is instructed otherwise?', '**Indirect prompt injection via tools** — can content returned by a tool (a web page, an email, a document) redirect the agent?', '**Tool description poisoning** — can a malicious or compromised MCP server describe its tools in a way that misleads the agent?', '**Loops and limits** — can the agent run indefinitely, repeat actions, or exceed spending and rate limits?', '**Logging** — is every tool call recorded with user identity, inputs and outputs?']),
    H('MCP-specific controls'),
    P('Good practice includes using only **approved, vetted MCP servers**; granting each the **minimum scopes** needed; authenticating users and passing their identity so actions respect their permissions; pinning versions; reviewing tool descriptions; and monitoring for unexpected tool use.'),
    BR('Agent testing is **access-control and segregation-of-duties testing** for a non-human actor. Ask: what can it do, under whose authority, with what approvals, and is it logged?'),
    AP(['List every tool and its permissions for the agent.', 'Test that high-risk actions require approval.', 'Test indirect injection through tool outputs.', 'Check MCP servers are approved and scoped.'])],
   ex: 'Testing showed a procurement agent could approve its own purchase orders if instructed via a supplier’s email. The fix separated “prepare” and “approve” into different tools with different authorities.' },
  { t: 'Real-world scenario: release testing for a banking assistant', blocks: [
    S('A strong release process turns testing into a **gate**: the assistant is only released when evidence shows it meets agreed criteria — and the evidence is kept.'),
    H('The situation'),
    P('A UAE bank is preparing version 2 of its customer assistant, adding Hindi support and the ability to block a lost card. The AI governance team defines the release evidence required.'),
    H('The release evidence pack'),
    CMP('Release gate for v2', ['Area', 'Evidence', 'Pass criteria'], [['Accuracy', '1,200-case evaluation set (Arabic, English, Hindi)', '≥ 95% correct; zero wrong fees'], ['Groundedness', 'Judge-model scores validated against 150 human-reviewed cases', '≥ 95% grounded; judge–human agreement ≥ 90%'], ['Refusal/escalation', '200 should-refuse cases', '≥ 98% correctly refused or escalated'], ['Language parity', 'Results per language', 'Each language within 3 points of English'], ['Security', 'Red-team report incl. indirect injection on card-block tool', 'No open critical/high findings'], ['Agent action', 'Card block requires in-app confirmation + step-up auth', 'Tested; cannot be bypassed by prompt'], ['Monitoring', 'Dashboards and alert owners for v2', 'Configured before launch']]),
    H('What happened'),
    P('The first run failed: Hindi correctness was 88%, and the red team triggered the card-block tool via a crafted message in a chat transcript the assistant summarised. The team improved Hindi retrieval and moved the card-block action behind an out-of-chat confirmation screen. The second run passed, and the evidence pack was signed by the product owner, compliance and security.'),
    BR('This is a **change approval board** with objective criteria and an evidence pack — the AI version of a release readiness review for a critical system.'),
    AP(['Define release criteria per area before testing.', 'Require evidence, not assurances, for each criterion.', 'Keep the signed evidence pack for audit.'], '', 'Building a GenAI release gate')],
   ex: 'Because the gate blocked the first release, the bank avoided launching a Hindi service that answered one in eight questions wrongly — and had evidence to show regulators how it controls changes.' }
 ],
 sum: ['GenAI testing combines automatic checks, rubrics, human review and adversarial testing.', 'An evaluation set needs coverage of tasks, languages, refusals, attacks and past failures.', 'Measure retrieval and groundedness separately; validate any judge model against humans.', 'Red-team reports need scope, coverage, severity ratings and retest evidence.', 'Agents need permission, approval, injection and logging tests; MCP servers must be vetted and scoped.', 'A release gate with defined criteria and an evidence pack turns testing into a control.'],
 q: [
  { t: 'An answer is factually correct but not supported by the retrieved sources. It is:', o: ['Correct but ungrounded', 'Grounded and complete', 'A retrieval success', 'Calibrated'], a: 0, x: 'It may be right, but it came from model memory, not the approved sources.' },
  { t: 'Why should a judge model be validated?', o: ['Regulations require at least two models for every decision', 'Judge models can be biased or mistaken, like any automated control', 'Validation makes the evaluation run faster and cheaper', 'Validating removes the need for any evaluation set at all'], a: 1, x: 'Compare judge scores with expert human scores to confirm reliability.' },
  { t: 'What should happen to a failure found in production?', o: ['Ignore it if it happened only once', 'Delete the related conversation logs', 'Add it permanently to the evaluation set', 'Raise the temperature to vary answers'], a: 2, x: 'Regression cases prevent the same failure returning.' },
  { t: 'A malicious tool server describes its tools in a way that misleads an agent. This risk is:', o: ['Gradual data drift', 'Model overfitting', 'A calibration error', 'Tool description poisoning'], a: 3, x: 'MCP and tool integrations can be abused through misleading tool metadata.' },
  { t: 'Which red-team report gives the most assurance?', o: ['Scope, coverage, rated findings and retest evidence', 'A one-line statement that no attacks succeeded', 'A list of only the attacks that succeeded', 'A vendor’s marketing summary of security'], a: 0, x: 'Assurance depends on coverage and remediation evidence.' },
  { t: 'Best control so an injected instruction cannot block or move money?', o: ['A longer and more detailed system prompt for the assistant', 'Out-of-chat confirmation and approval for high-risk actions', 'Raising the temperature so answers are less predictable', 'Adding more examples of good answers to the training data'], a: 1, x: 'Architectural approvals limit impact even if injection succeeds.' }
 ]
}
];
